//! Every route coolify-rs implements must exist upstream with the same
//! methods, group middleware and abilities. The inventory is regenerated by
//! `coolify-port` from upstream source, so an upstream change to a ported
//! route makes this test fail and the migration run escalate.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use coolify_api::routes::{Group, ROUTES};
use serde::Deserialize;

#[derive(Deserialize)]
struct Inventory {
    upstream_commit: String,
    routes: Vec<Route>,
}

#[derive(Deserialize)]
struct Route {
    methods: Vec<String>,
    uri: String,
    middleware: Vec<String>,
}

const MAIN: &[&str] = &[
    "api",
    "App\\Http\\Middleware\\Authenticate:sanctum",
    "App\\Http\\Middleware\\EnsureTokenBelongsToCurrentTeamMember",
    "App\\Http\\Middleware\\ApiAllowed",
    "App\\Http\\Middleware\\ApiSensitiveData",
];
const DISABLE: &[&str] = &[
    "api",
    "App\\Http\\Middleware\\ApiIpAllowed",
    "App\\Http\\Middleware\\Authenticate:sanctum",
    "App\\Http\\Middleware\\EnsureTokenBelongsToCurrentTeamMember",
];

#[test]
fn ported_routes_match_upstream_inventory() {
    let inv: Inventory =
        serde_json::from_str(include_str!("../../../compat/api/upstream-routes.json")).unwrap();
    let mut problems = Vec::new();
    for spec in ROUTES {
        let Some(up) = inv
            .routes
            .iter()
            .find(|r| r.uri == spec.uri && r.methods.iter().any(|m| m == spec.method))
        else {
            problems.push(format!(
                "{} {} no longer exists upstream",
                spec.method, spec.uri
            ));
            continue;
        };
        let group: &[&str] = match spec.group {
            Group::Public => &["api"],
            Group::Main => MAIN,
            Group::Disable => DISABLE,
        };
        let abilities: Vec<String> = up
            .middleware
            .iter()
            .filter_map(|m| m.strip_prefix("App\\Http\\Middleware\\ApiAbility:"))
            .map(str::to_string)
            .collect();
        let base: Vec<&str> = up
            .middleware
            .iter()
            .map(String::as_str)
            .filter(|m| !m.starts_with("App\\Http\\Middleware\\ApiAbility:"))
            // Named throttles are applied by their handlers (`rules::throttle`).
            .filter(|m| !m.starts_with("Illuminate\\Routing\\Middleware\\ThrottleRequests:"))
            .collect();
        if base != group {
            problems.push(format!(
                "{} {}: upstream middleware {:?} != expected group {:?}",
                spec.method, spec.uri, base, group
            ));
        }
        let ours: Vec<String> = spec
            .abilities
            .iter()
            .map(|any_of| {
                any_of
                    .iter()
                    .map(|a| a.as_str())
                    .collect::<Vec<_>>()
                    .join(",")
            })
            .collect();
        if ours != abilities {
            problems.push(format!(
                "{} {}: abilities upstream {:?} vs coolify-rs {:?}",
                spec.method, spec.uri, abilities, ours
            ));
        }
    }
    assert!(
        problems.is_empty(),
        "drift against upstream {}:\n{}",
        inv.upstream_commit,
        problems.join("\n")
    );
}

#[test]
fn coverage_summary() {
    let inv: Inventory =
        serde_json::from_str(include_str!("../../../compat/api/upstream-routes.json")).unwrap();
    let total: usize = inv
        .routes
        .iter()
        .filter(|r| !r.uri.ends_with("{any}"))
        .map(|r| r.methods.len())
        .sum();
    // Printed for reports; asserted loosely so new routes upstream do not fail it.
    println!(
        "coolify-rs implements {} of {} upstream API operations",
        ROUTES.len(),
        total
    );
    assert!(ROUTES.len() <= total);
}
